// Copied from plugins/pace-line/hooks/jobs/parse.ts by scripts/sync-shared.sh: edit it there.
// Parsers for what the batch-job watcher reads: squeue, scontrol, sacct, df,
// a log's tail and an sbatch submit line. watch.ts runs the commands.

import type { Disk, LogFlags } from '../../types'
import { slurmDuration } from '../slurm'

/** The squeue format the watcher asks for, one job per line, `|`-separated. */
export const SQUEUE_FORMAT = '%i|%j|%T|%M|%l|%D|%R|%b|%N|%V'

export type QueueRow = {
  id: string
  arrayId: string | null
  name: string
  state: string
  elapsedS: number | null
  limitS: number | null
  nodes: number
  /** The pending reason; for a running job squeue puts the node list here. */
  reason: string | null
  gpus: number | null
  gpuType: string | null
  nodeList: string
  /** As squeue prints it, local time without a zone. */
  submitTime: string
}

/** "gres/gpu:h200:4", "gres:gpu:4", "gres/gpu=2" or "N/A" → count and type. */
export function gpusFromTres(tres: string): { gpus: number | null; gpuType: string | null } {
  const m = /gpu(?::([a-zA-Z][\w.-]*))?[:=](\d+)/.exec(tres)
  if (!m) return { gpus: null, gpuType: null }
  return { gpus: Number(m[2]), gpuType: m[1] ? m[1].toUpperCase() : null }
}

export function parseSqueue(out: string): QueueRow[] {
  const rows: QueueRow[] = []
  for (const line of out.split('\n')) {
    if (!line.trim()) continue
    const [id = '', name = '', state = '', elapsed = '', limit = '', nodes = '', reason = '', tres = '', nodeList = '', submit = ''] = line.split('|')
    const arr = /^(\d+)_(\d+|\[.*\])$/.exec(id)
    const { gpus, gpuType } = gpusFromTres(tres)
    rows.push({
      id,
      arrayId: arr ? arr[1]! : null,
      name,
      state,
      elapsedS: slurmDuration(elapsed),
      limitS: slurmDuration(limit),
      nodes: Number(nodes) || 1,
      reason: state === 'PENDING' ? reason.replace(/^\(|\)$/g, '') || null : null,
      gpus,
      gpuType,
      nodeList: state === 'PENDING' ? '' : nodeList,
      submitTime: submit,
    })
  }
  return rows
}

/** `scontrol show job` as Key=Value; the first value wins (JobId before ArrayJobId's). */
export function scontrolFields(out: string): Record<string, string> {
  const kv: Record<string, string> = {}
  for (const m of out.matchAll(/(?:^|\s)(\w[\w/:]*)=(\S*)/g)) kv[m[1]!] ??= m[2]!
  return kv
}

export type JobDetail = {
  jobId: string
  isBatch: boolean
  workDir: string | null
  stdout: string | null
  command: string | null
  batchHost: string | null
  nodeList: string
}

export function parseJobDetail(out: string): JobDetail | null {
  const kv = scontrolFields(out)
  if (!kv.JobId) return null
  const val = (v: string | undefined) => (v && v !== '(null)' ? v : null)
  return {
    jobId: kv.JobId,
    isBatch: kv.BatchFlag === '1',
    workDir: val(kv.WorkDir),
    stdout: val(kv.StdOut),
    command: val(kv.Command),
    batchHost: val(kv.BatchHost),
    nodeList: val(kv.NodeList) ?? '',
  }
}

export const SACCT_FIELDS = 'JobID,JobName,State,ExitCode,Elapsed,WorkDir,SubmitLine'

export type Accounting = {
  jobId: string
  state: string
  exitCode: string
  elapsedS: number | null
  workDir: string | null
  submitLine: string | null
}

/**
 * `sacct -X -n -P -o <SACCT_FIELDS>` for one job. SubmitLine is last and may
 * itself hold `|` or newlines (an --wrap script), so it takes all the rest.
 * The state can read "CANCELLED by 1000"; only the first word is kept.
 */
export function parseSacct(out: string): Accounting | null {
  const text = out.replace(/\n+$/, '')
  if (!text.trim()) return null
  const parts = text.split('|')
  if (parts.length < 7) return null
  const [jobId = '', , state = '', exitCode = '', elapsed = '', workDir = ''] = parts
  const submitLine = parts.slice(6).join('|').trim()
  return {
    jobId,
    state: state.split(' ')[0] ?? state,
    exitCode,
    elapsedS: slurmDuration(elapsed),
    workDir: workDir || null,
    submitLine: submitLine || null,
  }
}

/** `date +%z` → minutes east of UTC: "-0400" → -240. */
export function zoneMinutes(z: string): number {
  const m = /^([+-])(\d\d)(\d\d)$/.exec(z.trim())
  return m ? (m[1] === '-' ? -1 : 1) * (Number(m[2]) * 60 + Number(m[3])) : 0
}

/** squeue's "2026-10-07T11:54:38" in the cluster's zone → epoch ms; null for N/A. */
export function slurmTime(text: string, zone: number): number | null {
  const ms = Date.parse(`${text}Z`)
  return Number.isNaN(ms) ? null : ms - zone * 60_000
}

/** `df -B1 --output=target,size,used,avail <paths>`. */
export function parseDf(out: string): Disk[] {
  return out.split('\n').slice(1).filter(l => l.trim()).map(l => {
    const [mount = '', size = '0', used = '0', avail = '0'] = l.trim().split(/\s+/)
    return { mount, size: Number(size), used: Number(used), avail: Number(avail) }
  })
}

/** Lines that say nothing about the job's progress. */
const NOISE = [
  /^\s*$/,
  /Kwargs passed to/,
  /(Future|User|Deprecation|Runtime)Warning/,
  /^\s*warnings\.warn/,
  /^\s*\d+%\|/, // a tqdm bar with no description: kept as progress, not as a line
]

export type LogTail = { lines: string[]; progress: { k: number; n: number } | null; flags: LogFlags }

/**
 * The tail of a job's log: tqdm's carriage returns split into lines, noise
 * dropped, the last `[k/N]` or tqdm `k/N [` as progress, and trouble flagged.
 */
export function parseLogTail(text: string, keep = 3): LogTail {
  const raw = text.replace(/\r\n/g, '\n').split(/[\r\n]/)
  let progress: { k: number; n: number } | null = null
  const flags: LogFlags = { oom: null, traceback: null, nccl: null, srun: null }
  let inTraceback = false
  for (let i = 0; i < raw.length; i++) {
    const line = raw[i]!
    const p = /\[(\d+)\/(\d+)\]/.exec(line) ?? /\b(\d+)\/(\d+) \[/.exec(line)
    if (p && Number(p[2]) > 0) progress = { k: Number(p[1]), n: Number(p[2]) }
    if (/CUDA out of memory|OutOfMemoryError|oom-kill|Out Of Memory/i.test(line)) flags.oom = line.trim()
    if (/NCCL (error|WARN.*[Tt]imeout)|Watchdog caught collective operation timeout|ProcessGroupNCCL.*(timeout|error)/i.test(line)) flags.nccl = line.trim()
    if (/^srun: error:/.test(line)) flags.srun = line.trim()
    if (/^Traceback \(most recent call last\)/.test(line)) inTraceback = true
    else if (inTraceback && /^\S/.test(line) && !/^(  |During handling|The above exception)/.test(line)) {
      // The first unindented line after the frames: "ValueError: ...".
      flags.traceback = line.trim()
      inTraceback = false
    }
  }
  const lines = raw.filter(l => !NOISE.some(r => r.test(l))).map(l => l.trimEnd()).slice(-keep)
  return { lines, progress, flags }
}

/** Splits a command line as a POSIX shell would for plain words, quotes and escapes. */
export function shellWords(line: string): string[] {
  const words: string[] = []
  let cur = ''
  let has = false
  let quote: '"' | "'" | null = null
  for (let i = 0; i < line.length; i++) {
    const c = line[i]!
    if (quote) {
      if (c === quote) quote = null
      else if (c === '\\' && quote === '"' && i + 1 < line.length) cur += line[++i]
      else cur += c
    } else if (c === '"' || c === "'") {
      quote = c
      has = true
    } else if (c === '\\' && i + 1 < line.length) {
      cur += line[++i]
      has = true
    } else if (/\s/.test(c)) {
      if (has || cur) words.push(cur)
      cur = ''
      has = false
    } else {
      cur += c
    }
  }
  if (has || cur) words.push(cur)
  return words
}

/**
 * The submit line as argv with RESUME=<ckpt> added to its --export (or an
 * `--export=ALL,RESUME=…` added after `sbatch`), any earlier RESUME replaced.
 * Null when the line is not a plain `sbatch … script` (a --wrap, an array, a pipe).
 */
export function resumeArgv(submitLine: string, ckpt: string): string[] | null {
  if (/\n|[|;&<>`]|\$\(/.test(submitLine)) return null
  const argv = shellWords(submitLine)
  if (argv[0] !== 'sbatch' && !argv[0]?.endsWith('/sbatch')) return null
  if (argv.some(a => a === '--wrap' || a.startsWith('--wrap=') || a === '-a' || a === '--array' || a.startsWith('--array='))) return null
  const set = (list: string) => [...list.split(',').filter(v => v && !v.startsWith('RESUME=')), `RESUME=${ckpt}`].join(',')
  const out = argv.filter(a => a !== '--parsable')
  for (let i = 1; i < out.length; i++) {
    const a = out[i]!
    if (a.startsWith('--export=')) {
      out[i] = `--export=${set(a.slice('--export='.length))}`
      return ['sbatch', '--parsable', ...out.slice(1)]
    }
    if (a === '--export' && i + 1 < out.length) {
      out[i + 1] = set(out[i + 1]!)
      return ['sbatch', '--parsable', ...out.slice(1)]
    }
  }
  return ['sbatch', '--parsable', `--export=ALL,RESUME=${ckpt}`, ...out.slice(1)]
}

/** "Submitted batch job 123" or a --parsable "123;cluster" → "123". */
export function submittedId(stdout: string): string | null {
  const m = /Submitted batch job (\d+)/.exec(stdout) ?? /^(\d+)(?:;\S+)?\s*$/m.exec(stdout)
  return m ? m[1]! : null
}

files.hooks/merge.ts:
// From what the jobs state knows to what a poll asks for, and from the reply's
// sections back to jobs, with pace-line's parsers doing the reading. Pure: the
// same steps as pace-line's poll, minus the commands, so they test without ssh.

import type { BatchJob, Ckpt, Disk, GpuSample, Jobs, NodeGpus } from '../types'
import { TERMINAL } from './jobs/alerts'
import { EMPTY_METRICS, addChunk, newestCkpt } from './jobs/metrics'
import { parseDf, parseJobDetail, parseLogTail, parseSacct, parseSqueue, slurmTime, zoneMinutes } from './jobs/parse'
import { byKey, parseFind, splitGpu } from './remote'
import type { Section, Want } from './remote'
import { parseNvidiaSmi } from './slurm'

/** Ended jobs stay listed this long. */
export const KEEP_ENDED_MS = 12 * 3600_000

export const EMPTY_JOBS: Jobs = { jobs: [], selected: null, updatedAt: null, error: null, disks: [], alerts: [] }

export const runDir = (j: BatchJob) => (j.workDir ? `${j.workDir.replace(/\/$/, '')}/runs/${j.jobId}` : null)

export function newJob(id: string): BatchJob {
  return {
    id,
    jobId: id,
    arrayId: null,
    name: '',
    state: 'PENDING',
    reason: null,
    elapsedS: null,
    limitS: null,
    nodes: 1,
    nodeList: '',
    gpus: null,
    gpuType: null,
    submittedAt: null,
    startedAt: null,
    workDir: null,
    stdout: null,
    command: null,
    submitLine: null,
    endedAt: null,
    exitCode: null,
    logSize: null,
    logChangedAt: null,
    lastLines: [],
    progress: null,
    flags: { oom: null, traceback: null, nccl: null, srun: null },
    metrics: null,
    ckpt: null,
    gpuReadings: null,
    gpusAt: null,
    idleSince: null,
    resumedFrom: null,
    resumedAs: null,
  }
}

/** Running jobs with GPUs, which the GPU sections and history are for. */
export const hasGpus = (j: BatchJob) => j.state === 'RUNNING' && (j.gpus ?? 0) > 0 && !!j.nodeList

/** The file reads of `jobs`: log tail, new metrics lines, checkpoints, a directory checkpoint's size. */
export function filesWant(jobs: readonly BatchJob[]): Pick<Want, 'logs' | 'metrics' | 'ckpts' | 'du'> {
  const w: Pick<Want, 'logs' | 'metrics' | 'ckpts' | 'du'> = { logs: [], metrics: [], ckpts: [], du: [] }
  for (const j of jobs) {
    if (j.stdout) w.logs.push({ id: j.id, path: j.stdout, knownSize: j.logSize })
    const dir = runDir(j)
    if (!dir) continue
    w.metrics.push({ id: j.id, path: `${dir}/metrics.jsonl`, offset: j.metrics?.offset ?? 0 })
    w.ckpts.push({ id: j.id, dir })
    if (j.ckpt && j.ckpt.sizeBytes === null) w.du.push({ id: j.id, path: j.ckpt.path })
  }
  return w
}

export type FullOpts = {
  nonce: string
  /** squeue ids whose scontrol said interactive: nothing to watch in them. */
  ignored: readonly string[]
  exclude: readonly string[]
  /** Jobs whose GPUs this pass reads. */
  gpuIds: readonly string[]
  isDfDue: boolean
}

/** A full poll: the queue, the files of running jobs already described, GPUs, maybe df. */
export function fullWant(s: Jobs, o: FullOpts): Want {
  const listed = s.jobs.filter(j => j.endedAt === null)
  return {
    nonce: o.nonce,
    queue: {
      knownRunning: [...listed.filter(j => j.state !== 'PENDING').map(j => j.id), ...o.ignored],
      knownPending: listed.filter(j => j.state === 'PENDING').map(j => j.id),
      active: listed.map(j => ({ id: j.id, jobId: j.jobId })),
      exclude: [...o.exclude],
    },
    ...filesWant(listed.filter(j => j.state === 'RUNNING' && (j.stdout || j.workDir))),
    gpus: s.jobs.filter(j => o.gpuIds.includes(j.id) && hasGpus(j)).map(j => ({ id: j.id, nodeList: j.nodeList })),
    df: o.isDfDue ? [...new Set(s.jobs.map(j => j.workDir).filter((w): w is string => !!w))] : null,
  }
}

export type QueueResult = {
  jobs: BatchJob[]
  /** Ids sacct showed ended in this pass. */
  ended: string[]
  /** Ids scontrol described in this pass while running: their files come next. */
  described: string[]
  /** Ids scontrol showed are interactive. */
  ignored: string[]
  zone: number | null
  disks: Disk[] | null
  error: string | null
}

/** A full reply merged into the jobs: squeue's rows, new details, the end of jobs it no longer lists. */
export function mergeQueue(prev: Jobs, sections: readonly Section[], t: number, o: { ignored: readonly string[]; exclude: readonly string[] }): QueueResult {
  const one = (name: string) => sections.find(s => s.name === name)?.body ?? null
  const zoneText = one('zone')
  const zone = zoneText ? zoneMinutes(zoneText.trim()) : null
  const df = one('df')
  const disks = df === null ? null : parseDf(df).filter((d, i, all) => all.findIndex(x => x.mount === d.mount) === i)
  const base = { ended: [], described: [], ignored: [], zone, disks }

  const failed = one('squeue-error')
  if (failed !== null) return { ...base, jobs: prev.jobs, error: `squeue: ${failed.trim().split('\n')[0] || 'failed'}` }
  const queue = one('squeue')
  if (queue === null) return { ...base, jobs: prev.jobs, error: 'the cluster sent no squeue' }

  const details = byKey(sections, 'detail')
  const sacct = byKey(sections, 'sacct')
  const ignore = new Set(o.ignored)
  const rows = parseSqueue(queue).filter(r => !o.exclude.includes(r.name) && !ignore.has(r.id))
  const byId = new Map(prev.jobs.map(j => [j.id, j]))
  const jobs: BatchJob[] = []
  const ended: string[] = []
  const described: string[] = []
  const ignored: string[] = []

  for (const r of rows) {
    const known = byId.get(r.id)
    let j: BatchJob = {
      ...(known ?? newJob(r.id)),
      arrayId: r.arrayId,
      name: r.name,
      state: r.state,
      reason: r.reason,
      elapsedS: r.elapsedS,
      limitS: r.limitS,
      nodes: r.nodes,
      nodeList: r.nodeList || known?.nodeList || '',
      gpus: r.gpus ?? known?.gpus ?? null,
      gpuType: r.gpuType ?? known?.gpuType ?? null,
      submittedAt: known?.submittedAt ?? slurmTime(r.submitTime, zone ?? 0),
    }
    if (j.state === 'RUNNING' && j.startedAt === null) j.startedAt = t - (r.elapsedS ?? 0) * 1000
    const text = details.get(r.id)
    if (text !== undefined) {
      const d = parseJobDetail(text)
      if (d && !d.isBatch) {
        ignored.push(r.id)
        continue
      }
      if (d) {
        j = { ...j, jobId: d.jobId, workDir: d.workDir, stdout: d.stdout, command: d.command, nodeList: d.nodeList || j.nodeList }
        if (j.state === 'RUNNING') described.push(j.id)
      }
    }
    jobs.push(j)
  }

  const listed = new Set(rows.map(r => r.id))
  for (const j of prev.jobs) {
    if (listed.has(j.id) || ignore.has(j.id)) continue
    if (j.endedAt !== null) {
      if (t - j.endedAt < KEEP_ENDED_MS) jobs.push(j)
      continue
    }
    const acct = parseSacct(sacct.get(j.id) ?? '')
    if (!acct || !TERMINAL.has(acct.state)) {
      jobs.push(j) // accounting lags squeue: ask again next pass
      continue
    }
    jobs.push({
      ...j,
      state: acct.state,
      exitCode: acct.exitCode,
      elapsedS: acct.elapsedS ?? j.elapsedS,
      submitLine: acct.submitLine,
      workDir: j.workDir ?? acct.workDir,
      endedAt: t,
    })
    ended.push(j.id)
  }
  return { jobs, ended, described, ignored, zone, disks, error: null }
}

/** One job's file sections, where the pass asked for them: log, metrics, checkpoint. */
export function applyFiles(j: BatchJob, sections: readonly Section[]): BatchJob {
  const get = (name: string, key = j.id) => {
    for (let i = sections.length - 1; i >= 0; i--) if (sections[i]!.name === name && sections[i]!.key === key) return sections[i]!.body
    return null
  }
  let out = j

  const logStat = get('logstat')
  if (logStat !== null) {
    const [size, mtime] = logStat.trim().split(/\s+/).map(Number)
    if (Number.isFinite(size) && size !== j.logSize) {
      const tail = get('log')
      if (tail !== null) {
        const t = parseLogTail(tail)
        out = {
          ...out,
          lastLines: t.lines,
          progress: t.progress ?? out.progress,
          // Sticky: an error scrolled out of the tail still happened.
          flags: {
            oom: t.flags.oom ?? out.flags.oom,
            traceback: t.flags.traceback ?? out.flags.traceback,
            nccl: t.flags.nccl ?? out.flags.nccl,
            srun: t.flags.srun ?? out.flags.srun,
          },
        }
      }
      out = { ...out, logSize: size!, logChangedAt: Number.isFinite(mtime) ? mtime! * 1000 : out.logChangedAt }
    }
  }

  const mStat = get('mstat')
  if (mStat !== null) {
    const from = Number(mStat.trim().split(/\s+/)[1])
    let m = out.metrics ?? EMPTY_METRICS
    if (from === 0 && m.offset > 0) m = EMPTY_METRICS // rewritten from scratch
    const chunk = get('metrics')
    if (chunk !== null && from === m.offset) m = addChunk(m, chunk)
    out = { ...out, metrics: m }
  }

  // Called only for jobs the pass read: no ckpt section means no such directory.
  const dir = runDir(j)
  if (dir) out = { ...out, ckpt: pickCkpt(dir, j.ckpt, [get('ckpt', `${j.id}|0`), get('ckpt', `${j.id}|1`)], get('du')) }
  return out
}

/** The newest checkpoint in runs/<id>/checkpoints, else in runs/<id> itself. */
function pickCkpt(dir: string, prev: Ckpt | null, bodies: readonly (string | null)[], du: string | null): Ckpt | null {
  const wheres = [`${dir}/checkpoints`, dir]
  for (let i = 0; i < wheres.length; i++) {
    const body = bodies[i]
    if (body === null || body === undefined) continue
    const top = newestCkpt(wheres[i]!, parseFind(body))
    if (!top) continue
    if (prev && prev.path === top.path && prev.mtimeMs === top.mtimeMs) {
      if (prev.sizeBytes !== null || du === null) return prev
      const n = Number(du.trim())
      return { ...prev, sizeBytes: Number.isFinite(n) && n > 0 ? n : null }
    }
    return top
  }
  return null
}

const anyIdle = (r: NodeGpus[] | null) => (r ?? []).some(n => n.gpus.some(g => (g.util ?? 0) === 0 && g.procs.length === 0))

/** A job's GPU sections, one per node, as pace-line reads them over ssh. */
export function applyGpus(j: BatchJob, sections: readonly Section[], nonce: string, t: number): BatchJob {
  const prefix = `${j.id}|`
  const readings: NodeGpus[] = []
  for (const s of sections) {
    if (s.name !== 'gpu' || !s.key.startsWith(prefix)) continue
    const { gpus, apps } = splitGpu(s.body, nonce)
    if (!gpus.trim()) continue
    readings.push({ node: s.key.slice(prefix.length), gpus: parseNvidiaSmi(gpus, apps) })
  }
  const r = readings.length ? readings : null
  return { ...j, gpuReadings: r ?? j.gpuReadings, gpusAt: t, idleSince: r === null ? j.idleSince : anyIdle(r) ? j.idleSince ?? t : null }
}

const pctOf = (used: number | null, total: number | null) => (used !== null && total ? Math.round((used / total) * 1000) / 10 : null)

/** The job's current GPU readings as one history sample, every GPU in percent. */
export function gpuSample(j: BatchJob): GpuSample | null {
  if (!j.gpuReadings || j.gpusAt === null) return null
  const gpus: GpuSample['gpus'] = {}
  for (const n of j.gpuReadings) {
    for (const g of n.gpus) gpus[`${n.node}:${g.index}`] = { util: g.util, mem: pctOf(g.memUsedMiB, g.memTotalMiB), power: pctOf(g.powerW, g.powerLimitW) }
  }
  return Object.keys(gpus).length ? { t: j.gpusAt, gpus } : null
}

/** History with `sample` added for `id` (once per reading), at most `max` samples, jobs no longer listed dropped. */
export function addHistory(h: Record<string, GpuSample[]>, adds: readonly { id: string; sample: GpuSample }[], keep: ReadonlySet<string>, max: number): Record<string, GpuSample[]> {
  const out: Record<string, GpuSample[]> = {}
  for (const [id, list] of Object.entries(h)) if (keep.has(id)) out[id] = list
  for (const { id, sample } of adds) {
    const list = out[id] ?? []
    if (list.length && list[list.length - 1]!.t >= sample.t) continue
    out[id] = [...list, sample].slice(-Math.max(1, max))
  }
  return out
}

files.hooks/remote.ts:
// One poll is one ssh round trip: a bash script, sent on stdin to the login
// node, runs what pace-line runs on the cluster and prints each output under a
// marker line. Pure: the script is built from what the poll wants, and the
// reply is split back into sections for pace-line's parsers.

import { SACCT_FIELDS, SQUEUE_FORMAT } from './jobs/parse'
import { APP_QUERY, GPU_QUERY } from './slurm'

/** The bytes of a log's end the pane reads, as pace-line does. */
export const LOG_TAIL_BYTES = 65_536
/** process.run keeps 4 MiB of stdout: what one poll may spend on metrics. */
export const METRICS_BUDGET = 3_000_000
/** A cluster file system that hangs shouldn't hang the poll. */
const FS_TIMEOUT = 'timeout 20'

/** What one poll asks the cluster for. */
export type Want = {
  /** Marks this reply's sections; a log line can't fake one. */
  nonce: string
  /**
   * squeue, then scontrol for jobs not yet described, then sacct for active
   * jobs squeue no longer lists. Null for a files- or GPU-only pass.
   */
  queue: {
    /** squeue ids described while running (or ignored): never asked again. */
    knownRunning: string[]
    /** squeue ids described while pending: asked again once they run. */
    knownPending: string[]
    /** Listed jobs not yet ended, as `id` and the jobId sacct takes. */
    active: { id: string; jobId: string }[]
    /** Job names never described (excludeNames). */
    exclude: string[]
  } | null
  logs: { id: string; path: string; knownSize: number | null }[]
  metrics: { id: string; path: string; offset: number }[]
  ckpts: { id: string; dir: string }[]
  du: { id: string; path: string }[]
  gpus: { id: string; nodeList: string }[]
  /** Work dirs for df, besides /scratch/$USER; null when not due. */
  df: string[] | null
}

export const EMPTY_WANT: Omit<Want, 'nonce'> = { queue: null, logs: [], metrics: [], ckpts: [], du: [], gpus: [], df: null }

/** A single-quoted shell word. */
export function shq(s: string): string {
  return `'${s.replace(/'/g, `'\\''`)}'`
}

/** The ssh argv one round trip runs; the script goes on stdin. */
export function sshArgv(host: string, remote: readonly string[]): string[] {
  return ['ssh', '-o', 'BatchMode=yes', '-o', 'ConnectTimeout=8', '-o', 'ServerAliveInterval=10', host, ...remote]
}

const ID = /^[\w.[\]-]+$/

/** The bash script for `w`. Every path and id is quoted; each command may fail alone. */
export function buildScript(w: Want): string {
  const n = w.nonce
  const out: string[] = [
    'set +e',
    'export LC_ALL=C',
    `S() { printf '\\n@@JW:${n}:%s:%s\\n' "$1" "$2"; }`,
    'S zone -; date +%z',
  ]

  if (w.queue) {
    const set = (ids: readonly string[]) => shq(` ${ids.filter(i => ID.test(i)).join(' ')} `)
    out.push(
      `q=$(squeue -u "$USER" -h -r -o ${shq(SQUEUE_FORMAT)} 2>&1); rc=$?`,
      'if [ $rc -eq 0 ]; then',
      '  S squeue -; printf \'%s\' "$q"',
      `  kr=${set(w.queue.knownRunning)}; kp=${set(w.queue.knownPending)}; xn=${shq(`|${w.queue.exclude.join('|')}|`)}`,
      `  printf '%s\\n' "$q" | while IFS='|' read -r id name state rest; do`,
      '    [ -z "$id" ] && continue',
      '    case "$xn" in *"|$name|"*) continue;; esac',
      '    case "$kr" in *" $id "*) continue;; esac',
      '    case "$kp" in *" $id "*) [ "$state" = RUNNING ] || continue;; esac',
      '    S detail "$id"; scontrol show job "$id" 2>/dev/null',
      '  done',
      `  ids=$(printf '%s\\n' "$q" | cut -d'|' -f1)`,
    )
    for (const a of w.queue.active) {
      if (!ID.test(a.id) || !ID.test(a.jobId)) continue
      out.push(`  printf '%s\\n' "$ids" | grep -qxF -- ${shq(a.id)} || { S sacct ${shq(a.id)}; sacct -j ${shq(a.jobId)} -X -n -P -o ${shq(SACCT_FIELDS)} 2>/dev/null; }`)
    }
    out.push('else', '  S squeue-error -; printf \'%s\' "$q"', 'fi')
  }

  for (const l of w.logs) {
    const known = l.knownSize === null ? '-1' : String(l.knownSize)
    out.push(`f=${shq(l.path)}; st=$(${FS_TIMEOUT} stat -c '%s %Y' -- "$f" 2>/dev/null) && { S logstat ${shq(l.id)}; printf '%s' "$st"; read -r sz mt <<<"$st"; [ "$sz" != ${shq(known)} ] && { S log ${shq(l.id)}; ${FS_TIMEOUT} tail -c ${LOG_TAIL_BYTES} -- "$f"; }; }`)
  }

  // A new job's whole file could pass the stdout cap: each read gets a share,
  // and addChunk keeps only whole lines, so the rest comes next poll.
  const cap = Math.max(200_000, Math.floor(METRICS_BUDGET / Math.max(1, w.metrics.length)))
  for (const m of w.metrics) {
    out.push(`m=${shq(m.path)}; off=${Math.max(0, Math.floor(m.offset))}; sz=$(${FS_TIMEOUT} stat -c %s -- "$m" 2>/dev/null) && { [ "$sz" -lt "$off" ] && off=0; S mstat ${shq(m.id)}; printf '%s %s' "$sz" "$off"; [ "$sz" -gt "$off" ] && { S metrics ${shq(m.id)}; ${FS_TIMEOUT} tail -c +$((off+1)) -- "$m" | head -c ${cap}; }; }`)
  }

  for (const c of w.ckpts) {
    const dir = c.dir.replace(/\/+$/, '')
    ;[`${dir}/checkpoints`, dir].forEach((d, i) => {
      out.push(`d=${shq(d)}; [ -d "$d" ] && { S ckpt ${shq(`${c.id}|${i}`)}; ${FS_TIMEOUT} find "$d" -mindepth 1 -maxdepth 1 -printf '%f|%y|%s|%T@\\n' 2>/dev/null | tail -n 200; }`)
    })
  }

  for (const d of w.du) out.push(`S du ${shq(d.id)}; ${FS_TIMEOUT} du -sb -- ${shq(d.path)} 2>/dev/null | cut -f1`)

  for (const g of w.gpus) {
    const remote = `nvidia-smi --query-gpu=${GPU_QUERY} --format=csv,noheader,nounits; echo @@JWAPPS:${n}; nvidia-smi --query-compute-apps=${APP_QUERY} --format=csv,noheader,nounits`
    out.push(`for h in $(scontrol show hostnames ${shq(g.nodeList)} 2>/dev/null); do S gpu ${shq(`${g.id}|`)}"$h"; timeout 15 ssh -n -o BatchMode=yes -o ConnectTimeout=5 "$h" ${shq(remote)} 2>/dev/null; done`)
  }

  if (w.df) out.push(`S df -; df -B1 --output=target,size,used,avail "/scratch/$USER" ${w.df.map(shq).join(' ')} 2>/dev/null`)

  out.push('S end -')
  // bash reads the script from stdin as it goes: wrapped in a function, it is
  // read whole before anything runs, and nothing inside can eat the rest.
  return ['main() {', ...out.map(l => `  ${l}`), '}', 'main </dev/null', ''].join('\n')
}

export type Section = { name: string; key: string; body: string }

/**
 * The reply's sections in order, each body byte for byte (the newline before
 * each marker belongs to the marker). `isComplete` is false when the reply
 * stopped before the end marker: ssh dropped, or stdout passed its cap.
 */
export function splitSections(stdout: string, nonce: string): { sections: Section[]; isComplete: boolean } {
  const mark = `\n@@JW:${nonce}:`
  const parts = stdout.split(mark)
  const sections: Section[] = []
  let isComplete = false
  for (const part of parts.slice(1)) {
    const nl = part.indexOf('\n')
    const head = nl === -1 ? part : part.slice(0, nl)
    const body = nl === -1 ? '' : part.slice(nl + 1)
    const colon = head.indexOf(':')
    const name = colon === -1 ? head : head.slice(0, colon)
    const key = colon === -1 ? '' : head.slice(colon + 1)
    if (name === 'end') {
      isComplete = true
      break
    }
    sections.push({ name, key, body })
  }
  return { sections, isComplete }
}

/** The sections of one name, by key; a key given twice keeps its last body. */
export function byKey(sections: readonly Section[], name: string): Map<string, string> {
  const m = new Map<string, string>()
  for (const s of sections) if (s.name === name) m.set(s.key, s.body)
  return m
}

export type Entry = { name: string; kind: 'file' | 'dir'; size: number; mtimeMs: number }

/** `find -printf '%f|%y|%s|%T@'` lines, as $.fs.list gives them to newestCkpt. */
export function parseFind(body: string): Entry[] {
  const out: Entry[] = []
  for (const line of body.split('\n')) {
    const parts = line.split('|')
    if (parts.length < 4) continue
    const t = Number(parts.pop())
    const size = Number(parts.pop())
    const y = parts.pop()
    const name = parts.join('|')
    if (!name || !Number.isFinite(t)) continue
    out.push({ name, kind: y === 'd' ? 'dir' : 'file', size: Number.isFinite(size) ? size : 0, mtimeMs: Math.round(t * 1000) })
  }
  return out
}

/** A gpu section's two nvidia-smi CSVs. */
export function splitGpu(body: string, nonce: string): { gpus: string; apps: string } {
  const mark = `@@JWAPPS:${nonce}\n`
  const i = body.indexOf(mark)
  return i === -1 ? { gpus: body, apps: '' } : { gpus: body.slice(0, i), apps: body.slice(i + mark.length) }
}

/** The first line of ssh's complaint, for the pane. */
export function sshError(stderr: string, exitCode: number): string {
  const line = stderr.split('\n').map(s => s.trim()).find(s => s && !/^Warning: Permanently added/.test(s))
  return line ? line.slice(0, 200) : `ssh exited with ${exitCode}`
}

